from html import escape
import re

def edit(g):
 p=g['pages'];intro=g['intro'];faq=g['faq'];config=g['config'];email=config['email'];endpoint=config['formEndpoint']
 g['nav']='<a href="/work/">Work</a><a href="/services/">Services</a><a href="/agency-partnerships/">Agency Partnerships</a><a href="/about/">About</a><a href="/contact/">Contact</a>'
 shared=[('How much will my project cost?','Each proposal is based on the deliverables, functionality, and support required. Share your priorities and any budget constraints so we can define a suitable scope.'),('How long does a website take?','The schedule depends on scope, content readiness, integrations, and approval turnaround. Milestones and dependencies are agreed before work begins.'),('How do revisions work?','Your proposal sets the review stages and revision rounds. Additional requests are assessed for cost and schedule impact before work proceeds.'),('What happens after launch?','You receive the agreed access and handover documentation. Maintenance and further improvements can be arranged separately.'),('Can you work with overseas clients?','Yes. We agree communication channels, review milestones, and a practical overlap window.'),('Who owns the website and files?','Ownership, licences, account access, and source-file delivery are documented in the agreement.')]
 def invitation(title='What would you like to build next?',copy='Tell me what your business does, what you want to improve, and where you are starting. We can use that conversation to define the right project.',cta='Discuss your project'):
  return f'<section class="editorialclosing"><span class="eyebrow">YOUR NEXT PROJECT</span><h2>{title}</h2><p>{copy}</p><a class="btn orange" href="/contact/">{cta} ↗</a></section>'
 def bullets(items):return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
 def reading(body):return '<section class="reading">'+body+'</section>'
 def form():
  booking=f'<a class="textlink booking" href="{escape(config["bookingUrl"])}">Book a discovery call ↗</a><p class="fine">Select your timezone on the booking page.</p>' if config['bookingUrl'] else ''
  return f'''<section class="contactsection"><div><span class="eyebrow">PROJECT ENQUIRY</span><h2>Tell me where<br>you are starting.</h2><p>You don’t need a complete brief. Share the project and the questions you have.</p><a class="email" href="mailto:{email}">{email} ↗</a>{booking}<p class="fine">Direct founder involvement · Based in India</p></div><form id="enquiry" {'action="'+escape(endpoint)+'" method="post"' if endpoint else ''} aria-describedby="form-note"><div class="formrow"><label>Name<input name="name" required maxlength="120" autocomplete="name"></label><label>Email<input name="email" required type="email" maxlength="254" autocomplete="email"></label></div><label>Business or agency name (optional)<input name="business" maxlength="200" autocomplete="organization"></label><label>Existing website (optional)<input type="url" name="website" maxlength="500" placeholder="https://"></label><label>Service needed<select required name="service"><option value="">Choose a service</option><option>Website design & development</option><option>Branding & graphic design</option><option>SEO & digital marketing</option><option>Agency partnership</option><option>Not sure yet</option></select></label><label>Project description<textarea required name="goal" minlength="10" maxlength="5000" rows="4" placeholder="What are you building or improving? Who is it for? What would make the project useful?"></textarea></label><div class="formrow"><label>Budget range (optional)<input name="budget" list="budget-options" maxlength="100" placeholder="Amount and currency, or Not sure"><datalist id="budget-options"><option value="Not sure"></datalist></label><label>Preferred timeline (optional)<select name="timeline"><option value="">Not specified</option><option>Within 1 month</option><option>1–3 months</option><option>3–6 months</option><option>Flexible</option></select></label></div><div class="honeypot" aria-hidden="true"><label>Leave blank<input name="_gotcha" tabindex="-1" autocomplete="off"></label></div><button type="submit" class="btn orange">{'Send project enquiry' if endpoint else 'Prepare email enquiry'} ↗</button><p id="form-note" class="fine">{'Your enquiry is submitted to the configured enquiry service.' if endpoint else 'Opens a draft in your email app. You must review and send it there; the website does not receive the enquiry.'} <a href="/privacy/">Privacy information</a></p><p id="formstatus" role="status" aria-live="polite" tabindex="-1"></p><noscript><p class="fine">Please email me directly using the address above.</p></noscript></form></section>'''
 # Replace shared full forms with short, page-specific invitations.
 for route,(title,body) in list(p.items()):
  pos=body.find('<section class="contactsection">')
  if pos>=0:body=body[:pos]+invitation()
  body=body.replace('Varanasi, India','India').replace('Varanasi','India').replace('with 10+ years of experience, ','').replace('10+ years of experience, ','')
  p[route]=(title,body)
 descriptions={}
 cards=[('/services/website-development/','Website design & development','A website that explains your offer, works across devices, and gives visitors a clear next step.',['Page structure and content guidance','Responsive layouts and development','Agreed forms, launch and handover']),('/services/design/','Branding & graphic design','A consistent visual identity and practical assets for your website, presentations, and campaigns.',['Colour and typography system','Logo development or refinement','Editable campaign and marketing assets']),('/services/seo-marketing/','SEO & digital marketing','Search foundations, useful content, and campaigns connected to measurable business goals.',['Technical and content review','Campaign and landing-page planning','Agreed measurement priorities']),('/agency-partnerships/','Agency partnerships','Additional design and development capacity, delivered under your brand with agreed client boundaries.',['Fixed-scope paid pilot','Written client-contact boundaries','Source files and documented handover'])]
 def servicecards(full=False):
  return '<div class="servicegrid">'+''.join(f'<a class="servicecard {"navy" if i==3 else ""}" href="{url}"><small>0{i+1}</small><h3>{title}</h3><p>{copy}</p>'+ (bullets(deliver) if full else '')+'<span>Explore '+('partnerships' if i==3 else 'service')+' ↗</span></a>' for i,(url,title,copy,deliver) in enumerate(cards))+'</div>'
 def example(url,title,copy):return f'<a class="relatedexample" href="{url}"><span class="eyebrow">RELEVANT EXAMPLE</span><h3>{title}</h3><p>{copy}</p><span>Explore the concept ↗</span></a>'
 # Homepage keeps the interaction and visual composition; updates editorial content.
 t,b=p['/'];b=b.replace('INDEPENDENT STUDIO. CONNECTED THINKING.','FOUNDER-LED DIGITAL STUDIO · BASED IN INDIA').replace('Custom websites with clear content, responsive design, and search foundations. Work directly with Kumar, from the first brief through launch.','I help businesses turn their ideas into clear, distinctive websites—and connect them with the design, content, and marketing they need next. You work directly with me, from the first conversation to handover.').replace('BASED IN INDIA <span>↗</span> BUILT FOR BUSINESSES EVERYWHERE','For businesses and agency partners, in India and beyond.').replace('Small details.<br>Whole new possibilities.','See the thinking<br>behind the design.').replace('Explore retail and architecture journeys.<br>See the working demos and design decisions.','Explore original concepts showing how visual identity, content, and website structure come together. Independent demonstrations, not commissioned projects.').replace('One connected studio.<br>Four ways forward.','One studio.<br>Connected services.').replace('Start with your website.<br>Build the right foundations around it.','Start with the project you need today. Add design, search, or marketing support when there is a clear reason to.')
 a=b.index('<div class="servicegrid">');z=b.index('</section>',a);b=b[:a]+servicecards()+b[z:]
 b=b.replace('Less guesswork.<br>More forward motion.','A clear path<br>from idea to launch.')
 stages=[('Discover','We discuss your business, audience, existing website, and priorities.'),('Scope','You receive a written proposal covering deliverables, responsibilities, milestones, and fees.'),('Design','We agree the visual direction and key layouts before development.'),('Build','I develop the agreed experience and share progress at the review points.'),('Test','We check layouts, navigation, forms, and agreed integrations before launch.'),('Launch','We complete the launch checklist and hand over access and documentation.'),('Support','Choose a separately scoped support arrangement if you need ongoing changes or maintenance.')]
 a=b.index('<div class="process">');z=b.index('</section>',a);b=b[:a]+'<div class="process">'+''.join(f'<div><span>{i+1:02}</span><h3>{title}</h3><p>{copy}</p></div>' for i,(title,copy) in enumerate(stages))+'</div>'+b[z:]
 b=b.replace('A real person.<br>From hello to handover.','The person you speak to<br>is the person doing the work.').replace('I’m Kumar Saurabh Mishra, the founder of SiteSutra. Based in India, I bring website development, design, SEO, and digital marketing together for businesses and agency partners.','I’m Kumar Saurabh Mishra, founder of SiteSutra. I bring website development, design, SEO, and digital marketing together so your project has a consistent direction and a clear line of communication.').replace('Direct access to the person doing the work','Direct founder involvement').replace('Agreed milestones and communication windows','Written scope and review milestones').replace('Clear ownership and documented handover','Agreed account and file ownership').replace('Transparent scope and separate support options','Documented handover').replace('Meet the founder ↗','About Kumar ↗')
 b=re.sub(r'<section class="proof">.*?</section>','',b,flags=re.S)
 b=b.replace(g['faq'](g['questions']),faq(shared))
 # FAQ generated in original source may already have revised pricing text.
 b=re.sub(r'<div class="faqs">.*?</div>',faq(shared),b,count=1,flags=re.S)
 p['/']=(t,b)
 p['/services/']=('Website, design, SEO & agency services',intro('SERVICES','Build the right foundations<br>for your next step.','A new website, a clearer identity, or a focused marketing project—SiteSutra brings the work together around your business needs.')+'<section>'+servicecards(True)+'</section><section class="relatedgrid">'+example('/work/olive-earth/','Olive & Earth','Explore responsive retail structure and a warm visual system.')+example('/work/form-space/','Form / Space','Explore a project-led studio website and consultation journey.')+'</section>'+invitation('Not sure where to start?','Share your current website and the problem you want to solve.','Find the right starting point'))
 website='''<h2>Best suited to</h2>'''+bullets(['Businesses launching their first website','Businesses replacing an unclear or outdated site','Campaigns needing a focused landing page','Agencies needing additional delivery capacity'])+'''<h2>Define the website you need.</h2><p>Your proposal defines the exact pages, features, and deliverables. Depending on the project, these can include:</p>'''+bullets(['Sitemap and page structure','Content guidance','Custom responsive layouts','Website development on the agreed platform','Forms and agreed integrations','Technical SEO foundations','Accessibility and performance checks','Launch preparation and handover'])+'''<h2>Request a tailored quote.</h2><p>Pricing depends on the pages, functionality, content readiness, and integrations required. Hosting, licences, substantial copywriting, and ongoing support are included only when specified in the proposal.</p><h2>What I need from you</h2><p>Before development, we agree who supplies copy, images, access, and approvals. The schedule accounts for these dependencies.</p><p><a class="textlink" href="/guides/scope/">Read what belongs in a website scope ↗</a></p>'''
 p['/services/website-development/']=('Website design & development',intro('WEBSITE DESIGN & DEVELOPMENT','A website that makes your<br>business easier to understand.','Your website should explain what you do, show why it matters, and help visitors take the next step. I combine content structure, visual design, and development to build that experience.')+reading(website)+'<section class="relatedgrid">'+example('/work/olive-earth/','A retail browsing journey','See how categories, product details and a demonstration basket connect.')+example('/work/form-space/','A project-led studio website','See how project stories and a consultation brief support a clear next step.')+'</section><section><h2>Before development begins</h2>'+faq([shared[1],shared[2],shared[3],shared[5],('Can the website connect to my existing tools?','We define the required systems and visitor tasks during scoping. Access, provider capabilities, and integration work are agreed in the proposal.')])+'</section>'+invitation('Plan your website.','Share your audience, the pages you need, and what visitors should be able to do.','Plan your website'))
 design='<h2>Possible deliverables</h2>'+bullets(['Visual direction and references','Logo development or refinement','Colour and typography system','Brand usage guidelines','Social and campaign templates','Presentation and marketing assets','Agreed editable source files and export formats'])+'<h2>From direction to usable assets</h2><p>Understand the business → agree direction → develop concepts → refine the selected direction → prepare final assets and guidance.</p><h2>A scope built around your assets</h2><p>Design projects are quoted around the assets and revision rounds you need. Ongoing design support can be scoped separately.</p>'
 p['/services/design/']=('Branding & graphic design',intro('BRANDING & GRAPHIC DESIGN','Give your business a visual<br>identity people can recognise.','I create visual systems and everyday design assets that help your business communicate consistently across its website, presentations, and marketing.')+reading(design)+'<section class="relatedgrid">'+example('/work/olive-earth/','A warm retail visual direction','See how palette, type and object imagery establish a consistent concept identity.')+example('/work/form-space/','A restrained studio visual direction','See how typography and project imagery give a different business its own voice.')+'</section><section><h2>Design questions</h2>'+faq([('Can you work with my existing brand?','Yes. A project can extend your current identity or develop a new direction, depending on the brief.'),('What files will I receive?','The proposal lists the editable files, export formats, usage guidance, and ownership terms included.'),shared[2]])+'</section>'+invitation('Discuss your design needs.','Tell me which assets you need and whether you already have a visual identity.','Discuss your design needs'))
 marketing=[('Search foundations','Review technical issues, page structure, titles, internal links, and content gaps to create a prioritised improvement plan.'),('Content planning','Identify questions your customers ask and develop content that helps them understand your offer and make decisions.'),('Campaigns and landing pages','Scope the channels, creative assets, landing pages, and tracking needed for an agreed campaign.'),('Measurement','Use agreed tracking and available data to review enquiries, relevant traffic, and next actions.')]
 audit='''<section class="sampleaudit" id="sample-plan"><span class="eyebrow">SAMPLE PLANNING ARTEFACT / ILLUSTRATIVE</span><h2>A plan you can act on.</h2><p>This example shows the structure of a prioritised review. It is not an audit of a real client, a finding about this website, or a performance result.</p><div class="tablewrap"><table><caption>Example review plan for a fictional service business</caption><thead><tr><th scope="col">Review question</th><th scope="col">Proposed action</th><th scope="col">Validation</th></tr></thead><tbody><tr><th scope="row">Does each service page explain the offer?</th><td>Clarify deliverables and link to the project enquiry.</td><td>Review page content and enquiry route.</td></tr><tr><th scope="row">Are buyer questions answered?</th><td>Plan a scope guide and a cost guide.</td><td>Check relevance and useful internal links.</td></tr><tr><th scope="row">Can we measure meaningful actions?</th><td>Agree consent and accepted-enquiry tracking.</td><td>Verify events against real submissions when configured.</td></tr></tbody></table></div></section>'''
 p['/services/seo-marketing/']=('SEO & digital marketing',intro('SEO & DIGITAL MARKETING','Help the right people<br>discover your business.','I connect search improvements, useful content, and campaign planning with a clear customer journey. The starting point is understanding your audience, current performance, and business priorities.')+'<section class="marketinggrid">'+''.join(f'<article><small>0{i+1}</small><h2>{h}</h2><p>{c}</p></article>' for i,(h,c) in enumerate(marketing))+'</section>'+audit+reading('<h2>Prepare your content for discovery across search experiences.</h2><p>Clear service information, accessible pages, original work, and consistent business details form a useful foundation. AI-search visibility can be monitored as an experiment, alongside conventional search and actual enquiries.</p><p>Google rankings, AI citations, lead volumes, and revenue are not guaranteed.</p><h2>Start with defined work.</h2><p>Start with a defined audit or implementation project. Ongoing work is scoped around agreed priorities. Advertising budgets are separate from management fees.</p><p><a class="textlink" href="/services/website-development/">Explore website foundations and landing pages ↗</a></p>')+'<section><h2>Search and measurement questions</h2>'+faq([('What should we measure?','Measures depend on your goals and tracking setup. Relevant enquiries and customer actions are more useful than treating traffic alone as success.'),('Can you guarantee rankings or AI recommendations?','No. The service covers defined work, transparent measurement, and ongoing decisions based on available evidence.'),('Is advertising spend included?','Advertising budgets are separate from management fees. Channels, creative assets and tracking are agreed in the campaign scope.')])+'</section>'+invitation('Discuss your search priorities.','Share your audience, current website, and the actions that matter to your business.','Discuss your search priorities'))
 partnership=[('Start with a paid pilot.','Choose one small deliverable with acceptance criteria, a timeline, and a fixed fee. Use the pilot to assess communication and delivery before commissioning more work.'),('Keep the relationship clear.','Your agency controls client communication. Any direct involvement with your client is agreed in writing.'),('Make handover practical.','Agree the source files, assets, access, documentation, and ownership terms before work starts.'),('Plan the working rhythm.','Set review milestones, communication channels, and a suitable time-overlap window.')]
 p['/agency-partnerships/']=('White-label agency partnerships',intro('AGENCY PARTNERSHIPS','Your client relationship.<br>Additional delivery capacity.','I support agencies with website design, development, landing pages, and agreed design or SEO tasks. Work can be delivered under your brand with clear responsibilities and handover requirements.')+'<section class="partnershipgrid">'+''.join(f'<article><small>0{i+1}</small><h2>{h}</h2><p>{c}</p></article>' for i,(h,c) in enumerate(partnership))+'</section>'+reading('<h2>Agree the boundaries before work starts.</h2><p>Confidentiality, revision rounds, acceptance criteria, and support responsibilities are written into the scope. Additional requests are reviewed for cost and schedule impact before work proceeds.</p><p><a class="textlink" href="/services/website-development/">Website delivery capabilities ↗</a></p>')+'<section class="relatedgrid">'+example('/work/olive-earth/','Retail concept delivery','Explore an implemented browsing and basket demonstration.')+example('/work/form-space/','Studio concept delivery','Explore an implemented project and consultation demonstration.')+'</section>'+invitation('Discuss an agency pilot.','Share one deliverable, your review requirements, and the working arrangement you need.','Discuss an agency pilot'))
 about='I’m Kumar Saurabh Mishra, the founder of SiteSutra, based in India. I work across website development, design, SEO, and digital marketing for businesses and agency partners.'
 p['/about/']=('About Kumar Saurabh Mishra',intro('ABOUT / FOUNDER-LED','Independent thinking.<br>Direct involvement.',about)+'<section class="founder aboutfounder"><figure class="founderart founderphoto"><img src="/assets/kumar-saurabh-mishra-founder.jpg" alt="Kumar Saurabh Mishra, founder of SiteSutra" width="800" height="800" loading="lazy" decoding="async"><figcaption><span>BASED IN VARANASI, INDIA</span><small>KUMAR SAURABH MISHRA / FOUNDER</small></figcaption></figure><div><h2>Understand the problem.<br>Define the work.</h2><p>My approach is straightforward: understand the problem, define the work, and keep decisions clear throughout the project. You speak directly with the person responsible for delivery.</p><p>Whether you need a website, a visual identity, or additional agency capacity, we start by agreeing what success means for the project and what is included.</p>'+bullets(['Direct founder involvement','Written scope and review milestones','Agreed account and file ownership','Documented handover'])+'</div></section>'+invitation('Tell me about your project.','Share your starting point and the work you need next.','Tell me about your project'))
 p['/contact/']=('Contact — discuss your project',intro('CONTACT','Let’s define your next project.','Share your business, your starting point, and what you want to change. You don’t need a complete brief to begin.')+form())
 p['/work/']=(p['/work/'][0],re.sub(r'<section class="pageintro">.*?</section>',intro('WORK / INDEPENDENT CONCEPTS','Original ideas, developed<br>into digital experiences.','These independent concepts demonstrate my approach to design and website structure. Explore the brief, decisions, and implementation. These are demonstrations, not commissioned projects.'),p['/work/'][1],count=1,flags=re.S))
 for route,(title,body) in list(p.items()):
  body=body.replace('Website concept · Lifestyle · Concept','Independent concept · Lifestyle retail').replace('Website concept · Architecture · Concept','Independent concept · Architecture').replace('A considered home for everyday objects.','A warm, product-led website concept for a fictional homeware brand.').replace('An architecture practice, brought into focus.','A project-led website concept for a fictional architecture practice.')
  body=body.replace('Objects / Materials / Story','Shop / Collections / About').replace('Everyday rituals.<br>Considered objects.','Everyday objects.<br>Thoughtfully chosen.').replace('Shop ceramics ↗','Explore the collection ↗').replace('Projects / Approach / Studio','Projects / Studio / Approach / Contact').replace('Architecture for<br>the way we live.','Spaces shaped around<br>the way we live.').replace('COURTYARD HOUSE / JAIPUR · FICTIONAL BRIEF','COURTYARD HOUSE / CONCEPT')
  body=body.replace('fictional locations,','project context,').replace('fictional location,','project context,').replace('location and project story','project context and story').replace('Buildings and project locations are fictional design briefs.','The buildings are visual studies, not commissioned work.')
  if route in ['/work/olive-earth/','/work/form-space/']:
   olive='olive-earth' in route
   body=body.replace('Product artwork is created in CSS. The catalogue and prices are illustrative.','Product illustrations and catalogue content were created for this concept.').replace('Architectural images are original vector concept illustrations.','Architectural imagery consists of original concept illustrations.')
   body=re.sub(r'<div><span class="eyebrow">BRIEF & AUDIENCE</span>.*?</div><div>', '<div><span class="eyebrow">BRIEF & AUDIENCE</span><h2>'+('A calm browsing experience.' if olive else 'A practice introduced through its work.')+'</h2><p>'+('Create a calm browsing experience that helps visitors explore objects by purpose, material, and collection. The implemented demo filters by product category and provides material and care details.' if olive else 'Create a website that introduces the practice through its work and makes consultation enquiries straightforward.')+'</p></div><div>',body,count=1,flags=re.S)
   body=body.replace('<h2>Demonstration boundaries</h2>','<h2>Implemented and proposed</h2><p>'+('Implemented: category filtering, expandable product details, material stories, and a page-local basket. Proposed: dedicated product pages, dimension specifications, checkout, and inventory integration; these are not implemented.' if olive else 'Implemented: project imagery, expandable project stories, studio approach, and a page-local consultation brief. Proposed: separate project pages and live consultation delivery; these are not implemented.')+'</p><h2>Concept note</h2>')
   body=body.replace('Discuss a similar project ↗','Discuss your project ↗')
   body=re.sub(r'<section class="editorialclosing">.*?</section>',invitation('Have a similar project in mind?','Share your business and the experience you want to create.','Discuss your project'),body,flags=re.S)
  if route=='/privacy/':
   body=body.replace('Project-brief delivery is not configured in this preview. The form does not transmit or save your entries. You can enquire directly by email.','The enquiry form prepares a draft in your email app. Entries are not submitted to or stored by this website. You must send the draft yourself. Your email provider processes the draft and sent message.').replace('name, email, chosen service, website, goal, budget if entered, and timeline','name, email, business name if entered, chosen service, website, description, budget if entered, and timeline')
  p[route]=(title,body)
 descriptions.update({r:re.sub('<[^>]*>','',title)+' — '+('Independent concept brief, design decisions, responsive previews and implemented interactions.' if r.startswith('/work/') else 'Direct founder involvement for businesses and agency partners in India and beyond.') for r,(title,b) in p.items()})
 descriptions.update({'/':'Founder-led websites, design, SEO and digital marketing by Kumar Saurabh Mishra. Work directly with SiteSutra from first conversation to handover.','/services/website-development/':'Content structure, custom responsive design, development, agreed integrations, technical SEO and handover. Request a tailored website quote.','/services/design/':'Visual identity, logo development, typography, brand guidelines and practical marketing assets with agreed editable files.','/services/seo-marketing/':'Search foundations, content planning, campaigns and transparent measurement. Scope an audit or implementation project.','/agency-partnerships/':'White-label design and development with written client boundaries, practical handover and a fixed-scope paid pilot.','/contact/':'Share your business, website and project priorities with Kumar Saurabh Mishra at SiteSutra. Prepare an email enquiry or contact directly.'})
 g['descriptions']=descriptions
